		CardData zack = makeJobForwardWithAutos("Zack", "Fire", 8000, "SOLDIER", "");
		placeP1Forward(mw, zack);
		mw.currentAbilitySource     = zack;
		mw.currentAbilitySourceIsP1 = true;

