		when(ctx.promptYouMay(any())).thenReturn(true);
		stubSearch(ctx, true);

		Consumer<GameContext> fn = ActionResolver.parse(MADEEN_EFFECT, makeForward("Madeen", "Light", 5, 0));
		assertNotNull(fn, "Madeen should parse");
