	/**
	 * 9-106R Ghis prints the same "return Ghis onto the field dull" wording but has just removed
	 * itself from the game, so it must not be replayed out of the Break Zone. That is why the
	 * wording is read inside the search parser rather than added to the shared play-onto-field
	 * pattern, and this pins Ghis to the parser it already had.
	 */
	@Test
	void ghisIsNotDivertedByVanillesReturnWording() {
		CardData ghis = makeForward("Ghis", "Ice", 4, 7000);
		String ghisEffect = "remove Ghis from the game. If you do so, return Ghis onto the field dull, "
				+ "then remove the top 3 cards of your deck from the game.";
		assertEquals("WhenYouDoSo", ActionResolver.fullDescription(ghisEffect, ghis));
	}


	// =========================================================================================
	// Titan 18-136S and Fenrir 24-065H: the two extra-cost Summons that refer back to the card
	// that paid the cost, rather than saying "If you paid the extra cost" like the other sixteen.
	//
	// That distinction is the whole reason they need resolution-time handling. The sixteen are
	// settled before the resolver ever sees them - applyExtraCostPaid/stripExtraCostClause rewrite
	// the text into one branch or the other - whereas these two have to read the payment itself,
	// through extraCostRemovedCardPower() and extraCostDiscardedCardCost().
	//
	// Fenrir was the more dangerous of the two: "break it and draw 1 card" contains "break it", so
	// the generic Break followup claimed it and broke the chosen Forward outright, with no cost
	// comparison and no extra cost paid. It counted as "fully parsed" in the coverage report the
	// whole time, because a wrong answer has no "?" in it.
	// =========================================================================================

	// --- Titan 18-136S --------------------------------------------------------------------

	private static final String TITAN_EFFECT =
			"Choose 1 Forward. Deal it damage equal to the power of the Forward removed by the extra cost.";

	@Test
	void titanDealsDamageEqualToTheRemovedForwardsPower() {
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = contextChoosing(List.of(t));
		when(ctx.extraCostRemovedCardPower()).thenReturn(8000);

		Consumer<GameContext> fn = ActionResolver.parse(TITAN_EFFECT, makeForward("Titan", "Earth", 4, 0));
		assertNotNull(fn, "Titan should parse");
		fn.accept(ctx);

		verify(ctx).damageTarget(t, 8000);
	}

	/**
	 * The extra cost is optional, and Titan is all payoff — cast without paying it, the Summon
	 * chooses a Forward and does nothing. Dealing 0 damage would not be the same thing: it still
	 * counts as having dealt damage to everything watching for that.
	 */
	@Test
	void titanDealsNoDamageAtAllWhenTheExtraCostWentUnpaid() {
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = contextChoosing(List.of(t));
		when(ctx.extraCostRemovedCardPower()).thenReturn(0);

		ActionResolver.parse(TITAN_EFFECT, makeForward("Titan", "Earth", 4, 0)).accept(ctx);

		verify(ctx, never()).damageTarget(any(), anyInt());
	}

	/** A Forward is still chosen either way — the choice is not conditional on the payment. */
	@Test
	void titanStillChoosesATargetWithoutTheExtraCost() {
		GameContext ctx = contextChoosing(List.of(new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD)));
		when(ctx.extraCostRemovedCardPower()).thenReturn(0);

		ActionResolver.parse(TITAN_EFFECT, makeForward("Titan", "Earth", 4, 0)).accept(ctx);

		verify(ctx).selectCharacters(
				anyInt(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), anyInt(), any(), anyInt(), any(),
				anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	// --- Fenrir 24-065H -------------------------------------------------------------------

	private static final String FENRIR_EFFECT =
			"Choose 1 Forward opponent controls. If its cost is equal to the cost of the card "
			+ "discarded by the extra cost, break it and draw 1 card.";

	/** Chooses an opposing Forward of the given cost and resolves Fenrir against it. */
	private static GameContext fenrirBoard(int chosenCost, int discardedCost) {
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = contextChoosing(List.of(t));
		when(ctx.p2Forward(0)).thenReturn(makeForward("Bahamut", "Fire", chosenCost, 9000));
		when(ctx.extraCostDiscardedCardCost()).thenReturn(discardedCost);
		return ctx;
	}

	@Test
	void fenrirBreaksAndDrawsWhenTheCostsMatch() {
		GameContext ctx = fenrirBoard(3, 3);

		Consumer<GameContext> fn = ActionResolver.parse(FENRIR_EFFECT, makeForward("Fenrir", "Ice", 3, 0));
		assertNotNull(fn, "Fenrir should parse");
		fn.accept(ctx);

		verify(ctx).breakTarget(new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD));
		verify(ctx).drawCards(1);
	}

	/** The regression: an unequal cost used to break the Forward anyway. */
	@Test
	void fenrirDoesNothingWhenTheCostsDiffer() {
		GameContext ctx = fenrirBoard(5, 3);

		ActionResolver.parse(FENRIR_EFFECT, makeForward("Fenrir", "Ice", 3, 0)).accept(ctx);

		verify(ctx, never()).breakTarget(any());
		verify(ctx, never()).drawCards(anyInt());
	}

	/** No discard means no cost to match — not a match against cost 0. */
	@Test
	void fenrirDoesNothingWhenTheExtraCostWentUnpaid() {
		GameContext ctx = fenrirBoard(0, 0);

		ActionResolver.parse(FENRIR_EFFECT, makeForward("Fenrir", "Ice", 3, 0)).accept(ctx);

		verify(ctx, never()).breakTarget(any());
		verify(ctx, never()).drawCards(anyInt());
	}

	/**
	 * Both cards must report a followup naming the extra-cost payoff. Fenrir reporting plain
	 * "Break" is what let a card that ignored its own condition sit in the "fully parsed" bucket.
	 */
	@Test
	void theExtraCostPayoffsAreNamedRatherThanReportedAsPlainBreakOrNothing() {
		assertEquals("ChooseCharacter / IfCostEqualsExtraCostDiscardBreakDraw",
				ActionResolver.fullDescription(FENRIR_EFFECT, makeForward("Fenrir", "Ice", 3, 0)));
		assertEquals("ChooseCharacter / DamageEqualToExtraCostPower",
				ActionResolver.fullDescription(TITAN_EFFECT, makeForward("Titan", "Earth", 4, 0)));
	}

	/**
	 * The sixteen "If you paid the extra cost" Summons are decided before the resolver sees them,
	 * and must stay that way — 18-084C Ramuh resolves to one damage figure or the other, never to
	 * an extra-cost lookup.
	 */
	@Test
	void theIfYouPaidWordingIsStillSettledBeforeResolution() {
		String ramuh = "Choose 1 Forward. Deal it 7000 damage. "
				+ "If you paid the extra cost, deal it 15000 damage instead.";
		assertEquals("Choose 1 Forward. Deal it 15000 damage.", ActionResolver.applyExtraCostPaid(ramuh));
		assertEquals("Choose 1 Forward. Deal it 7000 damage.", ActionResolver.stripExtraCostClause(ramuh));

		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = contextChoosing(List.of(t));
		ActionResolver.parse(ActionResolver.applyExtraCostPaid(ramuh), makeForward("Ramuh", "Lightning", 3, 0))
				.accept(ctx);
		verify(ctx).damageTarget(t, 15000);
		verify(ctx, never()).extraCostRemovedCardPower();
	}


	// =========================================================================================
	// Five action abilities, each blocked by a different thing.
	//
	//   Ninja 2-114C       needed the Battle pairing read from either side of it.
	//   Amidatelion 15-022C  a whole-board trait strip that moves no power at all.
	//   Hope 23-051L       the independent-sentence rule split it and resolved only the removal,
	//                      so Hope left the game and never came back.
	//   Chocobo 7-055R     the +3000 lend worked; the promise to follow the borrower off the
	//                      field was dropped, making it a free boost.
	//   Terra 1-047R       the only printing of the damage doubler that omits "instead".
	// =========================================================================================

	// --- Ninja 2-114C ---------------------------------------------------------------------

	private static final String NINJA_EFFECT =
			"Break Ninja as well as the Forward that blocks or is blocked by Ninja.";

	@Test
	void ninjaBreaksItselfAndItsBattlePartner() {
		CardData ninja = makeForward("Ninja", "Lightning", 3, 7000);
		ForwardTarget partner = new ForwardTarget(false, 2, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.combatBattlePartnerOf("Ninja")).thenReturn(partner);

		Consumer<GameContext> fn = ActionResolver.parse(NINJA_EFFECT, ninja);
		assertNotNull(fn, "Ninja should parse");
		fn.accept(ctx);

		verify(ctx).breakTarget(partner);
		verify(ctx).breakSourceCard(ninja);
	}

	/**
	 * The partner is broken first. Breaking Ninja first would shift the indices the partner target
	 * was resolved against whenever both sit on the same side of the field.
	 */
	@Test
	void ninjaBreaksThePartnerBeforeItself() {
		CardData ninja = makeForward("Ninja", "Lightning", 3, 7000);
		ForwardTarget partner = new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.combatBattlePartnerOf("Ninja")).thenReturn(partner);

		ActionResolver.parse(NINJA_EFFECT, ninja).accept(ctx);

		InOrder order = inOrder(ctx);
		order.verify(ctx).breakTarget(partner);
		order.verify(ctx).breakSourceCard(ninja);
	}

	/** Out of Battle there is no partner, and "Break Ninja" is unconditional either way. */
	@Test
	void ninjaStillBreaksItselfOutsideABattle() {
		CardData ninja = makeForward("Ninja", "Lightning", 3, 7000);
		GameContext ctx = mock(GameContext.class);
		when(ctx.combatBattlePartnerOf("Ninja")).thenReturn(null);

		ActionResolver.parse(NINJA_EFFECT, ninja).accept(ctx);

		verify(ctx).breakSourceCard(ninja);
		verify(ctx, never()).breakTarget(any());
	}

	// --- Amidatelion 15-022C --------------------------------------------------------------

	private static final String AMIDATELION_EFFECT =
			"Until the end of the turn, all the Forwards opponent controls lose Haste, First Strike and Brave.";

	@Test
	void amidatelionStripsTheThreeKeywordsFromEveryOpposingForward() {
		GameContext ctx = mock(GameContext.class);
		when(ctx.isP1()).thenReturn(true);
		when(ctx.p2ForwardCount()).thenReturn(3);
		ArgumentCaptor<ForwardTarget> targets = ArgumentCaptor.forClass(ForwardTarget.class);
		@SuppressWarnings("unchecked")
		ArgumentCaptor<EnumSet<CardData.Trait>> traits =
				(ArgumentCaptor<EnumSet<CardData.Trait>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(EnumSet.class);

		Consumer<GameContext> fn = ActionResolver.parse(AMIDATELION_EFFECT, makeForward("Amidatelion", "Water", 2, 0));
		assertNotNull(fn, "Amidatelion should parse");
		fn.accept(ctx);

		verify(ctx, times(3)).reduceTarget(targets.capture(), eq(0), traits.capture());
		assertEquals(EnumSet.of(CardData.Trait.HASTE, CardData.Trait.FIRST_STRIKE, CardData.Trait.BRAVE),
				traits.getValue(), "all three keywords, and no power change");
		for (ForwardTarget t : targets.getAllValues())
			assertFalse(t.isP1(), "only the opponent's Forwards");
	}

	/** Reads the opponent off isP1(), so a P2 caster strips P1's board rather than its own. */
	@Test
	void amidatelionStripsTheOtherSideWhenP2CastsIt() {
		GameContext ctx = mock(GameContext.class);
		when(ctx.isP1()).thenReturn(false);
		when(ctx.p1ForwardCount()).thenReturn(2);
		ArgumentCaptor<ForwardTarget> targets = ArgumentCaptor.forClass(ForwardTarget.class);

		ActionResolver.parse(AMIDATELION_EFFECT, makeForward("Amidatelion", "Water", 2, 0)).accept(ctx);

		verify(ctx, times(2)).reduceTarget(targets.capture(), eq(0), any());
		for (ForwardTarget t : targets.getAllValues()) assertTrue(t.isP1());
	}

	// --- Hope 23-051L ---------------------------------------------------------------------

	private static final String HOPE_EFFECT =
			"Remove Hope from the game. At the beginning of your next Main Phase 1, play Hope onto the field. "
			+ "You can only use this ability during your turn.";

	@Test
	void hopeRemovesItselfAndComesBackAtTheNextMainPhase1() {
		GameContext ctx = mock(GameContext.class);
		ArgumentCaptor<Consumer<GameContext>> queued = captorForConsumer();

		Consumer<GameContext> fn = ActionResolver.parse(HOPE_EFFECT, makeForward("Hope", "Water", 3, 7000));
		assertNotNull(fn, "Hope should parse");
		fn.accept(ctx);

		verify(ctx).removeNamedCardFromGame("Hope");
		verify(ctx).addPendingMainPhase1Effect(queued.capture());

		// The queued half is the part that used to be dropped entirely.
		GameContext later = mock(GameContext.class);
		queued.getValue().accept(later);
		verify(later).playNamedFromHoldingZoneOntoField("Hope");
	}

	@SuppressWarnings("unchecked")
	private static ArgumentCaptor<Consumer<GameContext>> captorForConsumer() {
		return (ArgumentCaptor<Consumer<GameContext>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(Consumer.class);
	}

	/**
	 * The independent-sentence rule is what claimed this text: both sentences name Hope outright,
	 * so neither refers back to the other and the splitter resolved them separately — the removal
	 * happened and the return was discarded. This pins the ability to the parser that reads both.
	 */
	@Test
	void hopeIsNotSplitIntoTwoIndependentSentences() {
		assertEquals("RemoveSelfReturnNextMainPhase1",
				ActionResolver.fullDescription(HOPE_EFFECT, makeForward("Hope", "Water", 3, 7000)));
	}

	/** The trailing restriction is a flag on the ability, gated at activation, not an effect. */
	@Test
	void hopesTurnRestrictionDoesNotBlockTheEffectFromParsing() {
		String withoutRestriction =
				"Remove Hope from the game. At the beginning of your next Main Phase 1, play Hope onto the field.";
		assertNotNull(ActionResolver.parse(withoutRestriction, makeForward("Hope", "Water", 3, 7000)));
		assertEquals("RemoveSelfReturnNextMainPhase1",
				ActionResolver.fullDescription(withoutRestriction, makeForward("Hope", "Water", 3, 7000)));
	}

