	// =========================================================================================
	// "When <Self> forms a party with <partner> and attacks" — six cards that fired on any party.
	//
	// AUTO_ABILITY_PATTERN's subject group runs up to the trigger word, so for these printings it
	// swallowed the whole party clause: "Lenne forms a party with Card Name Yuna and". That subject
	// contains the word "party", which is exactly what marks a subject as *being* the party rather
	// than naming a member of one, so the filter extraction skipped it and every one of the six
	// recorded no requirement at all — partner absent, carrier at home, the trigger fired anyway.
	// =========================================================================================

	private static AutoAbility partyTriggerOf(String cardText) {
		return CardData.parseAutoAbilities(cardText).stream()
				.filter(fa -> fa.trigger().equals("party attacks"))
				.findFirst().orElseThrow();
	}

	@Test
	void theCarrierAndItsPartnerAreBothRequired() {
		AutoAbility fa = partyTriggerOf(LENNE_2_142R);
		assertEquals("Lenne", fa.triggerCard(),
				"the subject reverts to the carrier, so the trigger reads like every other one");
		assertEquals(List.of("Lenne", "Yuna"), fa.partyCardNames());
	}

	@Test
	void twoPartnersAreAConjunctionNotAChoice() {
		// 12-044R Shikaree X wants Y *and* Z on the attack, which is why the filter is a list.
		AutoAbility fa = partyTriggerOf(
				"When Shikaree X forms a party with Card Name Shikaree Y and Card Name Shikaree Z "
				+ "and attacks, Shikaree X deals your opponent 3 points of damage.");
		assertEquals(List.of("Shikaree X", "Shikaree Y", "Shikaree Z"), fa.partyCardNames());
	}

	@Test
	void aCategoryPartnerBecomesACountFilterRatherThanAName() {
		// 20-034R Terra's partner is named by category, which is what partyMinCount counts.
		AutoAbility fa = partyTriggerOf(
				"When Terra forms a party with a Category VI Forward and attacks, you may cast 1 "
				+ "Summon of cost 4 or less from your hand without paying the cost.");
		assertEquals("Terra", fa.triggerCard());
		assertEquals(List.of("Terra"), fa.partyCardNames());
		assertEquals("VI", fa.partyCategory());
		assertEquals(1, fa.partyMinCount());
	}

	@Test
	void thePlainNamedPartySubjectIsUnchanged() {
		// "When a Card Name Chocobo you control forms a party and attacks" (9-050C) names a member
		// of the party rather than the carrier, and goes through the branch it always did.
		AutoAbility fa = partyTriggerOf(
				"When a Card Name Chocobo you control forms a party and attacks, draw 1 card.");
		assertEquals(List.of("Chocobo"), fa.partyCardNames());
	}

	@Test
	void everyNameOnTheListMustBeInTheParty() {
		MainWindow mw = new MainWindow();
		advanceTo(mw, GameState.Player.P1, GameState.GamePhase.MAIN_1);
		CardData lenne = makeForward("Lenne", "Water", 3, 7000, List.of());
		CardData yuna  = makeForward("Yuna",  "Water", 4, 7000, List.of());
		CardData other = makeForward("Rikku", "Water", 2, 5000, List.of());
		AutoAbility fa = partyTriggerOf(LENNE_2_142R);

		assertTrue(mw.autoAbilityTriggers.partyAttackMatchesFilter(fa, List.of(lenne, yuna)),
				"the carrier and the named partner are both attacking");
		assertFalse(mw.autoAbilityTriggers.partyAttackMatchesFilter(fa, List.of(lenne, other)),
				"the partner the ability names is not in the party");
		assertFalse(mw.autoAbilityTriggers.partyAttackMatchesFilter(fa, List.of(yuna, other)),
				"a carrier sitting at home did not form the party its ability describes");
	}

	// =========================================================================================
	// "Your opponent selects N … they control" — some forty printings, resolved as if it read
	// "choose N … opponent controls".
	//
	// Three things were wrong with that, and the card text asks for all three:
	//
	//   * The wrong player decided. Comprehensive rule 11.11.5.1 — "the player specified in the
	//     card text makes the required declaration". The text specifies the opponent, and which of
	//     their own Characters they can best afford to lose is the whole decision.
	//   * "Cannot be chosen" was applied. A select is not a choose — the rules say so in as many
	//     words, once per ability kind (11.3.3, 11.6.5, 11.7.5, 11.8.4, 11.8.9, 11.8.19) — and
	//     every one of those immunities is printed in terms of being *chosen*. Getting past them
	//     is what this wording is for, so honouring them against it read the card backwards.
	//   * The AI could not use any of them. The sweep that acted on the picks filtered to P2's
	//     side alone, so when P2 controlled the effect — its opponent being P1 — the selection was
	//     made and then silently dropped, and forty cards did nothing whatsoever in its hands.
	// =========================================================================================

	private static final String OPP_SELECTS_BREAK =
			"Your opponent selects 1 Forward they control. Put it into the Break Zone.";

	/** A mocked context whose select primitive hands back {@code picks}. */
	private static GameContext opponentSelectsContext(List<ForwardTarget> picks) {
		GameContext ctx = mock(GameContext.class);
		when(ctx.opponentSelectsOwnCharacters(anyInt(), anyBoolean(), any(), any(),
				anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(), any()))
				.thenReturn(new ArrayList<>(picks));
		return ctx;
	}

	@Test
	void theOpponentIsTheOneWhoSelects() {
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = opponentSelectsContext(List.of(t));

		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(ctx);

		verify(ctx).opponentSelectsOwnCharacters(eq(1), anyBoolean(), any(), any(),
				anyInt(), any(), eq(true), eq(false), eq(false), any());
		verify(ctx, never()).selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	@Test
	void aSelectIsActedOnWhicheverSideOfTheBoardItLandsOn() {
		// The regression that made these forty cards inert for the AI: with P2 controlling the
		// effect its opponent is P1, so the picks come back on P1's side, and a sweep that only
		// ever looked at P2's threw them away.
		ForwardTarget onP1 = new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = opponentSelectsContext(List.of(onP1));

		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(ctx);

		verify(ctx).forceTargetToBreakZone(onP1);
	}

	@Test
	void bothSidesOfASplitSelectionAreActedOn() {
		ForwardTarget onP1 = new ForwardTarget(true,  0, ForwardTarget.CardZone.FORWARD);
		ForwardTarget onP2 = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = opponentSelectsContext(List.of(onP1, onP2));

		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(ctx);

		verify(ctx).forceTargetToBreakZone(onP1);
		verify(ctx).forceTargetToBreakZone(onP2);
	}

	// ---- The rules distinction, on a real board -----------------------------------------------

	private static CardData shieldedForward(String name, int cost) {
		String text = name + " cannot be chosen by your opponent's abilities.";
		return new CardData(null, name, "Fire", cost, 7000, "Forward", false, 0, false, false,
				Set.of(), 0, List.of(), null, List.of(),
				List.of(), List.of(), CardData.parseFieldAbilities(text, "Forward"),
				List.of(), List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
				false, false, null, false, false, false, false, false, 1, null, null, null, text);
	}

	@Test
	void aSelectGetsPastCannotBeChosen() {
		MainWindow mw = new MainWindow();
		advanceTo(mw, GameState.Player.P1, GameState.GamePhase.MAIN_1);
		CardData warded = shieldedForward("Warded", 3);
		mw.gameState.getIdentity().put(warded, false);
		mw.placeP2CardInForwardZone(warded);

		// The shield really is in force against a P1 ability — this is the check the choose path
		// consults, and it says no.
		assertTrue(mw.isProtectedFromChoice(warded, false, true, false, null),
				"the Forward is genuinely protected from being chosen by a P1 ability");

		// P1 controls the effect, so the opponent doing the selecting is the AI and the whole
		// thing resolves without a prompt.
		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(mw.buildGameContext(true));

		assertTrue(mw.p2ForwardCards.isEmpty(),
				"a select is not a choose, so \"cannot be chosen\" does not answer it");
	}

	@Test
	void theAiGivesUpTheCheapestCharacterItCanSpare() {
		MainWindow mw = new MainWindow();
		advanceTo(mw, GameState.Player.P1, GameState.GamePhase.MAIN_1);
		seatP2Forwards(mw, List.of(
				makeForward("Costly",  "Fire", 7, 9000),
				makeForward("Cheapest", "Fire", 1, 3000),
				makeForward("Middle",  "Fire", 4, 7000)));

		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(mw.buildGameContext(true));

		assertEquals(List.of("Costly", "Middle"),
				mw.p2ForwardCards.stream().map(CardData::name).toList(),
				"choosing which of your own to lose is a question about what you can spare");
	}

	@Test
	void thePrintedFilterStillNarrowsWhatMayBeSelected() {
		// The filter belongs to the card, not to the immunity machinery: dropping the latter must
		// not drop the former.
		MainWindow mw = new MainWindow();
		advanceTo(mw, GameState.Player.P1, GameState.GamePhase.MAIN_1);
		seatP2Forwards(mw, List.of(makeForward("Cheap", "Fire", 2, 5000)));

		ActionResolver.parse(
				"Your opponent selects 1 Forward of cost 5 or more they control. "
				+ "Put it into the Break Zone.", null)
				.accept(mw.buildGameContext(true));

		assertEquals(1, mw.p2ForwardCards.size(),
				"nothing on their board clears the printed threshold, so nothing is selected");
	}

	@Test
	void aSelectDoesNotFireTheChosenByOpponentTriggers() {
		// Those watchers all read "when [this] is chosen by your opponent's Summon or ability".
		String watchText = "When Watcher is chosen by your opponent's Summons or abilities, draw 1 card.";
		CardData watcher = new CardData(null, "Watcher", "Fire", 3, 7000, "Forward", false, 0, false, false,
				Set.of(), 0, List.of(), null, List.of(),
				List.of(), CardData.parseAutoAbilities(watchText), List.of(),
				List.of(), List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
				false, false, null, false, false, false, false, false, 1, null, null, null, watchText);
		assertEquals("chosen by opponent's summon or ability",
				watcher.autoAbilities().get(0).trigger(),
				"the watcher carries the trigger this select must leave alone");

		MainWindow mw = new MainWindow();
		advanceTo(mw, GameState.Player.P1, GameState.GamePhase.MAIN_1);
		mw.gameState.initializeDeck(List.of(), List.of(
				makeForward("P2 Deck A", "Fire", 2, 5000),
				makeForward("P2 Deck B", "Fire", 2, 5000)));
		mw.gameState.getP2Hand().clear();
		mw.gameState.getIdentity().put(watcher, false);
		mw.placeP2CardInForwardZone(watcher);

		ActionResolver.parse(OPP_SELECTS_BREAK, null).accept(mw.buildGameContext(true));

		assertTrue(mw.p2ForwardCards.isEmpty(), "the select still took it");
		assertTrue(mw.gameState.getP2Hand().isEmpty(),
				"but it was selected, not chosen, so the watcher never fired");
	}

	// =========================================================================================
	// "Choose N …. Put it into the Break Zone." — a followup the choose chain had no reading for.
	//
	// The name chain had an entry for it, so these abilities described themselves as
	// "ChooseCharacter / PutToBreakZone" and looked implemented in every report. The choose chain
	// itself had none: FOLLOWUP_PUT_TO_BREAK_ZONE was referenced in exactly two places, the name
	// chain and tryParseOpponentSelects. So each of these logged a line and stopped, without even
	// offering a selection — 12-107R Lunafreya, 24-100C Cecil, 3-142H Famed Mimic Gogo, 18-127C
	// Lilisette, 17-121H Frimelda's quoted grant, and 18-097R Rinoa.
	//
	// It is the *forced* removal, not a break: "put into the Break Zone" moves the card whatever it
	// says about not being broken, which is what separates it from the Break arm beside it.
	// =========================================================================================

	/** Runs {@code text} against a mock whose selection hands back {@code picks}. */
	private static GameContext resolveChoose(String text, int xValue, List<ForwardTarget> picks) {
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean()))
				.thenReturn(new ArrayList<>(picks));
		Consumer<GameContext> fn = ActionResolver.parse(text, null, xValue);
		assertNotNull(fn, text);
		fn.accept(ctx);
		return ctx;
	}

	@Test
	void chooseThenPutIntoTheBreakZoneRemovesWhatWasChosen() {
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = resolveChoose("Choose 1 Forward. Put it into the Break Zone.", 0, List.of(t));

		verify(ctx).forceTargetToBreakZone(t);
	}

	@Test
	void itIsAForcedMoveRatherThanABreak() {
		// The distinction is the whole reason the two arms are separate: a Forward that cannot be
		// broken is still put into the Break Zone by this one.
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = resolveChoose("Choose 1 Forward. Put it into the Break Zone.", 0, List.of(t));

		verify(ctx, never()).breakTarget(any());
	}

	@Test
	void lilisettesPrintedFilterReachesTheSelection() {
		// 18-127C, the one printing of this shape that narrows what may be chosen.
		GameContext ctx = resolveChoose(
				"choose 1 Forward of cost 2 or less opponent controls. Put it into the Break Zone.",
				0, List.of());

		verify(ctx).selectCharacters(eq(1), anyBoolean(), eq(true), anyBoolean(), any(), any(),
				eq(2), eq("less"), anyInt(), any(),
				eq(true), eq(false), eq(false),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	@Test
	void bothSidesOfTheBoardAreSweptInDescendingOrder() {
		// Removing a card closes the zone list up, so the higher index has to go first or the
		// second removal lands on the survivor that slid into its place.
		ForwardTarget low  = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		ForwardTarget high = new ForwardTarget(false, 2, ForwardTarget.CardZone.FORWARD);
		ForwardTarget mine = new ForwardTarget(true,  1, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = resolveChoose("Choose 3 Forwards. Put them into the Break Zone.", 0,
				List.of(low, high, mine));

		InOrder order = inOrder(ctx);
		order.verify(ctx).forceTargetToBreakZone(mine);
		order.verify(ctx).forceTargetToBreakZone(high);
		order.verify(ctx).forceTargetToBreakZone(low);
	}

	// ---- What the anchored followup deliberately leaves alone -----------------------------------

	@Test
	void theDelayedFormIsNotTakenAsAnImmediateRemoval() {
		// 17-109R Cúchulainn: "At the beginning of the next Main Phase 1, put it into the Break
		// Zone." Those are the same words about a later turn, and it stays unimplemented rather
		// than resolving now — which would be worse than not resolving at all.
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = resolveChoose(
				"Choose 1 Forward. At the beginning of the next Main Phase 1, put it into the Break Zone.",
				0, List.of(t));

		verify(ctx, never()).forceTargetToBreakZone(any());
		verify(ctx, never()).breakTarget(any());
	}

	@Test
	void theInsteadFormKeepsItsOwnReading() {
		// 25-089R Cagnazzo: the Break Zone is the alternative branch of a return-to-hand, already
		// read as one. The new arm must not claim it off the trailing sentence.
		ForwardTarget t = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = resolveChoose(
				"choose 1 Forward opponent controls. Return it to its owner's hand. "
				+ "If you control a Card Name Golbez, put it into the Break Zone instead.",
				0, List.of(t));

		verify(ctx).returnP2ForwardToHand(0);
	}

	// ---- Rinoa: a chosen card's cost measured in X ----------------------------------------------

	@Test
	void aChooseMayMeasureCostInTheXThatWasPaid() {
		// 18-097R Rinoa, whose blocker was one step earlier than the followup: "of cost X or less"
		// never matched the choose header at all, so the sentence reached no followup to begin with.
		GameContext ctx = resolveChoose(
				"choose 1 Forward of cost X or less. Put it into the Break Zone.", 3, List.of());

		verify(ctx).selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				eq(3), eq("less"), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	@Test
	void aCostOfZeroIsStillARealFilter() {
		// Unlike a count of X, which declines at zero because choosing none is not a choice, a cost
		// of 0 names the cost 0 cards and is a filter like any other.
		GameContext ctx = resolveChoose(
				"choose 1 Forward of cost X or less. Put it into the Break Zone.", 0, List.of());

		verify(ctx).selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				eq(0), eq("less"), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	@Test
	void rinoasWholeTriggerIsRecognised() {
		AutoAbility etf = CardData.parseAutoAbilities(
				"When Rinoa enters the field, you may pay 《X》. When you do so, "
				+ "choose 1 Forward of cost X or less. Put it into the Break Zone.").get(0);
		assertTrue(AutoAbilityTriggers.dispatchedByTriggers(etf, null),
				"the payment run is what the triggers dispatch, and its sub-effect now resolves");
	}

	// =========================================================================================
	// Effect wiring — 19-037R Wol, 14-098R Ultimecia, 23-058C Dark Knight and 13-081H Lightning.
	//
	// Four abilities that had no reading at all between them, plus two that had one and got it
	// wrong. Grouped because they share the shape the resolver kept getting caught by: a sentence
	// whose meaning is set by a clause some earlier matcher was happy to stop in front of.
	// =========================================================================================

	// ---- 19-037R Wol: "exactly N", and Multi-Element as a search filter -------------------------

	private static final String WOL_19_037R_TEXT =
			"if there are exactly 3 different Elements among Characters you control, "
			+ "you may search for 1 Multi-Element Forward and add it to your hand.";

	/** Resolves an effect against a mock whose field shows {@code distinctElements} Elements. */
	private static GameContext resolveWithDistinctElements(String text, int distinctElements) {
		Consumer<GameContext> fn = ActionResolver.parse(text, null);
		assertNotNull(fn, "effect should parse");
		GameContext ctx = mock(GameContext.class);
		when(ctx.selfDistinctElementCount(anyBoolean(), anyBoolean(), anyBoolean()))
				.thenReturn(distinctElements);
		when(ctx.promptYouMay(any())).thenReturn(true);
		fn.accept(ctx);
		return ctx;
	}

	@Test
	void wolSearchesOnExactlyThreeElements() {
		GameContext ctx = resolveWithDistinctElements(WOL_19_037R_TEXT, 3);
		// The element filter reaches the deck scan as the pseudo-element "Multi-Element", which
		// CardData.containsElement resolves to "prints more than one".
		verify(ctx).searchDeckForCard(eq(true), eq(false), eq(false), eq(false),
				anyInt(), any(), any(), any(), any(), eq("Multi-Element"), any(), any(),
				eq("hand"), eq(1), anyBoolean(), any());
	}

	@Test
	void wolDoesNotSearchOnFourElements() {
		// The whole point of the wording: a fourth Element takes the search away again, where the
		// "N or more" reading this gate used to have would have kept it.
		GameContext ctx = resolveWithDistinctElements(WOL_19_037R_TEXT, 4);
		verify(ctx, never()).searchDeckForCard(anyBoolean(), anyBoolean(), anyBoolean(), anyBoolean(),
				anyInt(), any(), any(), any(), any(), any(), any(), any(),
				any(), anyInt(), anyBoolean(), any());
	}

	@Test
	void wolDoesNotSearchOnTwoElements() {
		GameContext ctx = resolveWithDistinctElements(WOL_19_037R_TEXT, 2);
		verify(ctx, never()).searchDeckForCard(anyBoolean(), anyBoolean(), anyBoolean(), anyBoolean(),
				anyInt(), any(), any(), any(), any(), any(), any(), any(),
				any(), anyInt(), anyBoolean(), any());
	}

	@Test
	void theOrMoreReadingStillMeansOrMore() {
		// 22-111L Raegen's comparator, which the same pattern now carries alongside Wol's.
		GameContext ctx = resolveWithDistinctElements(
				"if there are 3 or more different Elements among Characters you control, draw 1 card.", 4);
		verify(ctx).drawCards(1);
	}

	// ---- 14-098R Ultimecia: give a Forward, take one of the same cost ---------------------------

	private static final String ULTIMECIA_14_098R_TEXT =
			"select 1 Forward you control. Put it into the Break Zone. When you do so, "
			+ "choose 1 Forward of the same cost as the Forward you put into the Break Zone. "
			+ "You gain control of it.";

	@Test
	void ultimeciaResolvesAsOneExchange() {
		Consumer<GameContext> fn = ActionResolver.parse(ULTIMECIA_14_098R_TEXT, null);
		assertNotNull(fn, "Ultimecia's trigger should parse");
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).selectOwnForwardToBzThenGainControlOfSameCost();
		// The three sentences are one effect: nothing may run the closing choose on its own, which
		// is what the generic choose chain would have done with it.
		verify(ctx, never()).selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(),
				anyBoolean(), any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
		verify(ctx, never()).selectControlledTypeAndBreak(anyBoolean(), anyBoolean(), anyBoolean());
	}

	@Test
	void thePlainSelectToBreakZoneKeepsItsOwnReading() {
		// The two-sentence printing this one extends must still take the shorter route.
		Consumer<GameContext> fn = ActionResolver.parse(
				"select 1 Forward you control. Put it into the Break Zone.", null);
		assertNotNull(fn);
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).selectControlledTypeAndBreak(true, false, false);
		verify(ctx, never()).selectOwnForwardToBzThenGainControlOfSameCost();
	}

	// ---- 23-058C Dark Knight: keywords in front of a damage-scaled boost ------------------------

	private static final String DARK_KNIGHT_TEXT =
			"choose 1 Forward. Until the end of the turn, it gains Brave and +1000 power "
			+ "for each point of damage you have received. If you control 5 or more Backups, "
			+ "until the end of the turn, all the Forwards you control gain Brave and +1000 power "
			+ "for each point of damage you have received instead.";

	/** Resolves Dark Knight with {@code damage} in the user's damage zone and the gate as given. */
	private static GameContext resolveDarkKnight(int damage, boolean fiveBackups) {
		Consumer<GameContext> fn = ActionResolver.parse(DARK_KNIGHT_TEXT, null);
		assertNotNull(fn, "Dark Knight's trigger should parse");
		ForwardTarget chosen = new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.selfDamageCount()).thenReturn(damage);
		when(ctx.controlConditionMet(any())).thenReturn(fiveBackups);
		when(ctx.selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(chosen)));
		fn.accept(ctx);
		return ctx;
	}

	@Test
	void darkKnightGrantsBothBraveAndTheScaledPower() {
		GameContext ctx = resolveDarkKnight(4, false);
		// Before this, FOLLOWUP_KEYWORD_GRANT_UNTIL claimed the sentence off "it gains Brave" and
		// the power clause behind it was dropped entirely.
		verify(ctx).boostTarget(new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD),
				4000, EnumSet.of(CardData.Trait.BRAVE));
	}

	@Test
	void darkKnightScalesOffTheAbilityUsersOwnDamage() {
		// selfDamageCount, not p1DamageCount: the AI plays this card too.
		GameContext ctx = resolveDarkKnight(0, false);
		verify(ctx).selfDamageCount();
		verify(ctx).boostTarget(any(), eq(0), eq(EnumSet.of(CardData.Trait.BRAVE)));
	}

	@Test
	void darkKnightWithFiveBackupsBoostsTheWholeFieldInstead() {
		GameContext ctx = resolveDarkKnight(3, true);
		verify(ctx).applyMassFieldPowerBoost(eq(3000), eq(true), eq(false), eq(false), eq(true),
				any(), anyInt(), any(), any(), any());
		verify(ctx).applyMassFieldKeywordGrant(eq(EnumSet.of(CardData.Trait.BRAVE)),
				eq(true), eq(false), eq(false), eq(true), any(), anyInt(), any(), any());
		// "instead" — one branch or the other, never both.
		verify(ctx, never()).boostTarget(any(), anyInt(), any());
	}

	@Test
	void darkKnightWithoutFiveBackupsLeavesTheRestOfTheFieldAlone() {
		GameContext ctx = resolveDarkKnight(3, false);
		verify(ctx, never()).applyMassFieldPowerBoost(anyInt(), anyBoolean(), anyBoolean(),
				anyBoolean(), anyBoolean(), any(), anyInt(), any(), any(), any());
	}

	// ---- 13-081H Lightning: one allowance across two zones, given back on the way out -----------

	private static final String LIGHTNING_ETF =
			"choose up to 2 Forwards opponent controls or Forwards in your Break Zone. "
			+ "Remove them from the game.";
	private static final String LIGHTNING_LTF =
			"return each card removed by Lightning's ability to its owner's hand.";

	@Test
	void lightningOffersBothPoolsAsOneChoice() {
		Consumer<GameContext> fn = ActionResolver.parse(LIGHTNING_ETF, null);
		assertNotNull(fn, "Lightning's arrival should parse");
		ForwardTarget onField = new ForwardTarget(false, 1, ForwardTarget.CardZone.FORWARD);
		ForwardTarget inBz    = new ForwardTarget(true, 0, ForwardTarget.CardZone.BREAK_ZONE);
		GameContext ctx = mock(GameContext.class);
		when(ctx.selectForwardsOppFieldOrOwnBreakZone(anyInt(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(onField, inBz)));
		fn.accept(ctx);

		verify(ctx).selectForwardsOppFieldOrOwnBreakZone(2, true);
		verify(ctx).removeTargetFromGame(onField);
		verify(ctx).removeTargetFromGame(inBz);
		// The zone-switching choose route cannot span both pools, so it must not be the one used.
		verify(ctx, never()).selectCharactersFromBreakZone(anyInt(), anyBoolean(), anyBoolean(),
				anyBoolean(), any(), any(), anyInt(), any(), anyInt(), any(), anyBoolean(),
				anyBoolean(), anyBoolean(), any(), any(), any(), any(), anyBoolean(), any(), anyBoolean());
	}

	@Test
	void lightningRemovesTheHigherIndexFirst() {
		// Two picks in one Break Zone: taking the lower index first would slide the higher one
		// onto a different card.
		Consumer<GameContext> fn = ActionResolver.parse(LIGHTNING_ETF, null);
		assertNotNull(fn);
		ForwardTarget low  = new ForwardTarget(true, 0, ForwardTarget.CardZone.BREAK_ZONE);
		ForwardTarget high = new ForwardTarget(true, 3, ForwardTarget.CardZone.BREAK_ZONE);
		GameContext ctx = mock(GameContext.class);
		when(ctx.selectForwardsOppFieldOrOwnBreakZone(anyInt(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(low, high)));
		fn.accept(ctx);

		InOrder order = inOrder(ctx);
		order.verify(ctx).removeTargetFromGame(high);
		order.verify(ctx).removeTargetFromGame(low);
	}

	@Test
	void lightningsDepartureGivesBackItsOwnPile() {
		CardData lightning = makeForward("Lightning", "Lightning", 7, 9000);
		Consumer<GameContext> fn = ActionResolver.parse(LIGHTNING_LTF, lightning);
		assertNotNull(fn, "Lightning's departure should parse");
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).returnCardsRemovedBySourceToOwnersHands(lightning);
		// RETURN_NAMED_TO_OWNERS_HAND used to take the whole description for a card name and hunt
		// the field for a card called "each card removed by Lightning's ability".
		verify(ctx, never()).returnNamedCardToOwnersHand(any());
	}

	@Test
	void aPlainReturnByNameStillGoesTheOldWay() {
		CardData lightning = makeForward("Lightning", "Lightning", 7, 9000);
		Consumer<GameContext> fn = ActionResolver.parse("Return Shantotto to its owner's hand.", lightning);
		assertNotNull(fn);
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).returnNamedCardToOwnersHand("Shantotto");
		verify(ctx, never()).returnCardsRemovedBySourceToOwnersHands(any());
	}

	@Test
	void anotherCardsRemovedPileIsNotLightningsToGiveBack() {
		// The parser is self-named: a text naming some other card is not this ability.
		CardData other = makeForward("Vincent", "Dark", 4, 7000);
		assertNull(ActionResolverHand.tryParseReturnRemovedBySourceToOwnersHand(LIGHTNING_LTF, other),
				"a pile belonging to a different card is not this parser's to claim");
	}

	// ---- 14-098R Ultimecia on a real board ------------------------------------------------------

	@Test
	void ultimeciaTradesAForwardForOneOfTheSameCost() {
		// Resolved from P2's seat, where the AI answers both halves and no dialog is shown.
		MainWindow mw = new MainWindow();
		CardData give  = makeForward("Give", "Water", 4, 5000);   // P2's own, cost 4
		CardData prize = makeForward("Prize", "Fire", 4, 8000);   // P1's, cost 4 — the same cost
		CardData decoy = makeForward("Decoy", "Ice", 6, 9000);    // P1's, cost 6 — the wrong cost
		mw.gameState.getIdentity().put(give, false);
		mw.placeP2CardInForwardZone(give);
		placeP1Forward(mw, prize);
		placeP1Forward(mw, decoy);

		mw.buildGameContext(false).selectOwnForwardToBzThenGainControlOfSameCost();

		assertEquals(List.of("Prize"), mw.p2ForwardCards.stream().map(CardData::name).toList(),
				"the Forward given up is gone and the one of matching cost has changed hands");
		assertEquals(List.of("Decoy"), mw.p1ForwardCards.stream().map(CardData::name).toList(),
				"the Forward of a different cost was never eligible");
		assertEquals(List.of("Give"), mw.gameState.getP2BreakZone().stream().map(CardData::name).toList(),
				"and the price was paid into the Break Zone");
	}

	@Test
	void ultimeciaTakesNothingWhenThereIsNothingToGiveUp() {
		MainWindow mw = new MainWindow();
		CardData prize = makeForward("Prize", "Fire", 4, 8000);
		placeP1Forward(mw, prize);

		mw.buildGameContext(false).selectOwnForwardToBzThenGainControlOfSameCost();

		assertEquals(List.of(prize), mw.p1ForwardCards,
				"the whole ability hangs off \"When you do so\" — no put, no prize");
		assertTrue(mw.p2ForwardCards.isEmpty());
	}

	// ---- 13-081H Lightning on a real board -----------------------------------------------------

	@Test
	void lightningTakesFromBothZonesAndGivesItAllBackOnTheWayOut() {
		// Resolved from P2's seat so the AI answers the selection; from there the "opponent
		// controls" half is P1's field and the "your Break Zone" half is P2's.
		MainWindow mw = new MainWindow();
		CardData lightning = makeForward("Lightning", "Lightning", 7, 9000);
		CardData theirs    = makeForward("Theirs", "Ice", 3, 6000);
		CardData buried    = makeForward("Buried", "Wind", 4, 7000);
		mw.gameState.getIdentity().put(lightning, false);
		mw.gameState.getIdentity().put(buried, false);
		mw.placeP2CardInForwardZone(lightning);
		placeP1Forward(mw, theirs);
		mw.gameState.getP2BreakZone().add(buried);

		// The removals are credited to whatever ability is resolving, which is how the departure
		// half finds them again.
		mw.currentAbilitySource = lightning;
		ActionResolver.parse(LIGHTNING_ETF, lightning).accept(mw.buildGameContext(false));

		assertTrue(mw.p1ForwardCards.isEmpty(), "the opponent's Forward was removed from the game");
		assertTrue(mw.gameState.getP2BreakZone().isEmpty(), "and so was the one in the user's Break Zone");
		assertEquals(List.of(theirs), mw.gameState.getP1PermanentRfp());
		assertEquals(List.of(buried), mw.gameState.getP2PermanentRfp());

		ActionResolver.parse(LIGHTNING_LTF, lightning).accept(mw.buildGameContext(false));

		assertEquals(List.of(theirs), mw.gameState.getP1Hand(),
				"each card goes to its own owner, not to whoever played Lightning");
		assertEquals(List.of(buried), mw.gameState.getP2Hand());
		assertTrue(mw.gameState.getP1PermanentRfp().isEmpty());
		assertTrue(mw.gameState.getP2PermanentRfp().isEmpty());
	}

	@Test
	void everyRemovedCardGoesHomeToItsOwnOwner() {
		MainWindow mw = new MainWindow();
		CardData lightning = makeForward("Lightning", "Lightning", 7, 9000);
		CardData mine      = makeForward("Mine", "Fire", 2, 5000);
		CardData theirs    = makeForward("Theirs", "Ice", 3, 6000);
		mw.gameState.getIdentity().put(lightning, true);
		mw.gameState.getIdentity().put(mine, true);
		mw.gameState.getIdentity().put(theirs, false);
		mw.gameState.addToPermanentRfp(mine);
		mw.gameState.addToPermanentRfp(theirs);
		mw.cardsRemovedBySource.put(lightning, new ArrayList<>(List.of(mine, theirs)));

		mw.buildGameContext(true).returnCardsRemovedBySourceToOwnersHands(lightning);

		assertTrue(mw.gameState.getP1Hand().contains(mine), "the user's own card comes back to them");
		assertTrue(mw.gameState.getP2Hand().contains(theirs),
				"the opponent's Forward goes to the opponent, not to whoever played Lightning");
		assertTrue(mw.gameState.getP1PermanentRfp().isEmpty(), "and neither is still removed");
		assertTrue(mw.gameState.getP2PermanentRfp().isEmpty());
		assertFalse(mw.cardsRemovedBySource.containsKey(lightning),
			"the pile is spent — a second departure has nothing left to give back");
	}

	@Test
	void aCardThatLeftTheRemovedZoneIsNotConjuredBack() {
		MainWindow mw = new MainWindow();
		CardData lightning = makeForward("Lightning", "Lightning", 7, 9000);
		CardData gone      = makeForward("Gone", "Fire", 2, 5000);
		mw.gameState.getIdentity().put(lightning, true);
		mw.gameState.getIdentity().put(gone, true);
		// Recorded as removed by Lightning, but something has since taken it out of the RFP zone.
		mw.cardsRemovedBySource.put(lightning, new ArrayList<>(List.of(gone)));

		mw.buildGameContext(true).returnCardsRemovedBySourceToOwnersHands(lightning);

		assertFalse(mw.gameState.getP1Hand().contains(gone),
				"only what is still removed from the game comes home");
	}

	@Test
	void theUnionPoolHoldsOpponentForwardsAndOwnBreakZoneForwards() {
		// Resolved from P2's seat, so the AI branch answers and no dialog is shown. From there the
		// "opponent controls" half is P1's field and the "your Break Zone" half is P2's.
		MainWindow mw = new MainWindow();
		CardData theirs   = makeForward("Theirs", "Ice", 3, 6000);      // P1's field — the opponent's
		CardData ours     = makeForward("Ours", "Fire", 2, 5000);       // P2's field — the user's own
		CardData buried   = makeForward("Buried", "Wind", 4, 7000);     // P2's Break Zone
		mw.gameState.getIdentity().put(theirs, true);
		mw.gameState.getIdentity().put(ours, false);
		mw.gameState.getIdentity().put(buried, false);
		placeP1Forward(mw, theirs);
		mw.placeP2CardInForwardZone(ours);
		mw.gameState.getP2BreakZone().add(buried);

		List<ForwardTarget> picked =
				mw.buildGameContext(false).selectForwardsOppFieldOrOwnBreakZone(2, true);

		assertEquals(2, picked.size(),
				"one allowance of 2 filled from both pools — the user's own Forward is not in either");
		assertTrue(picked.contains(new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD)),
				"the opponent's field is offered");
		assertTrue(picked.contains(new ForwardTarget(false, 0, ForwardTarget.CardZone.BREAK_ZONE)),
				"and so is the ability user's own Break Zone");
		assertTrue(picked.stream().noneMatch(
					t -> t.zone() == ForwardTarget.CardZone.FORWARD && !t.isP1()),
				"but the user's own field is not — the text says the Forwards opponent controls");
	}

	// =========================================================================================
	// Effect wiring — 13-080C Marach and 23-049C Ninja.
	//
	// Both had a reading that stopped short: each parsed, named itself, and then dropped the
	// clause that says what actually happens. Marach made no selection at all and dealt no
	// damage; Ninja chose a Forward and gave it nothing.
	// =========================================================================================

	// ---- 13-080C Marach: the selection names the Forward that is spared ------------------------

	private static final String MARACH_TEXT =
			"your opponent selects 1 Forward they control. "
			+ "Deal 4000 damage to all the other Forwards opponent controls.";

	@Test
	void marachDamagesEveryForwardTheOpponentDidNotSpare() {
		MainWindow mw = new MainWindow();
		CardData spared = makeForward("Spared", "Lightning", 3, 9000);
		CardData b      = makeForward("B", "Lightning", 3, 9000);
		CardData c      = makeForward("C", "Lightning", 3, 9000);
		for (CardData x : List.of(spared, b, c)) mw.gameState.getIdentity().put(x, false);
		mw.placeP2CardInForwardZone(spared);
		mw.placeP2CardInForwardZone(b);
		mw.placeP2CardInForwardZone(c);

		// Resolved from P1's seat, so the opponent making the selection is the AI at P2, which
		// takes the first of its eligible Forwards.
		ActionResolver.parse(MARACH_TEXT, null).accept(mw.buildGameContext(true));

		assertEquals(0, mw.p2ForwardDamage.get(0), "the Forward the opponent selected is the one spared");
		assertEquals(4000, mw.p2ForwardDamage.get(1), "every other Forward they control takes the damage");
		assertEquals(4000, mw.p2ForwardDamage.get(2));
	}

	@Test
	void marachLeavesTheAbilityUsersOwnForwardsAlone() {
		MainWindow mw = new MainWindow();
		CardData mine   = makeForward("Mine", "Lightning", 3, 9000);
		CardData spared = makeForward("Spared", "Lightning", 3, 9000);
		CardData theirs = makeForward("Theirs", "Lightning", 3, 9000);
		mw.gameState.getIdentity().put(spared, false);
		mw.gameState.getIdentity().put(theirs, false);
		placeP1Forward(mw, mine);
		mw.placeP2CardInForwardZone(spared);
		mw.placeP2CardInForwardZone(theirs);

		ActionResolver.parse(MARACH_TEXT, null).accept(mw.buildGameContext(true));

		assertEquals(0, mw.p1ForwardDamage.get(0),
				"\"all the other Forwards opponent controls\" is one side of the board, not both");
		assertEquals(4000, mw.p2ForwardDamage.get(1));
	}

	@Test
	void marachWithOneOpposingForwardHitsNothing() {
		// The opponent spares their only Forward, so the complement is empty.
		MainWindow mw = new MainWindow();
		CardData only = makeForward("Only", "Lightning", 3, 9000);
		mw.gameState.getIdentity().put(only, false);
		mw.placeP2CardInForwardZone(only);

		ActionResolver.parse(MARACH_TEXT, null).accept(mw.buildGameContext(true));

		assertEquals(0, mw.p2ForwardDamage.get(0));
		assertEquals(1, mw.p2ForwardCards.size(), "and nothing is broken");
	}

	@Test
	void marachMakesTheSelectionRatherThanSkippingIt() {
		// The followup used to fall through to the not-yet-implemented warning, which returned
		// before the opponent was ever asked.
		Consumer<GameContext> fn = ActionResolver.parse(MARACH_TEXT, null);
		assertNotNull(fn);
		GameContext ctx = mock(GameContext.class);
		when(ctx.opponentSelectsOwnCharacters(anyInt(), anyBoolean(), any(), any(), anyInt(), any(),
				anyBoolean(), anyBoolean(), anyBoolean(), any())).thenReturn(new ArrayList<>());
		fn.accept(ctx);

		verify(ctx).opponentSelectsOwnCharacters(eq(1), anyBoolean(), any(), any(), anyInt(), any(),
				eq(true), eq(false), eq(false), any());
	}

	// ---- 23-049C Ninja: a quoted block restriction, granted to one Forward or to all -----------

	private static final String NINJA_TEXT =
			"choose 1 Forward. It gains \"This Forward cannot be blocked by a Forward of cost 3 or more.\" "
			+ "until the end of the turn. If you control 5 or more Backups, all the Forwards you control "
			+ "gain \"This Forward cannot be blocked by a Forward of cost 3 or more.\" until the end of the "
			+ "turn instead.";
	private static final String NINJA_MASS_CLAUSE =
			"all the Forwards you control gain \"This Forward cannot be blocked by a Forward of cost 3 "
			+ "or more.\" until the end of the turn.";

	@Test
	void ninjaGrantsTheBlockRestrictionToTheChosenForward() {
		Consumer<GameContext> fn = ActionResolver.parse(
				"choose 1 Forward. It gains \"This Forward cannot be blocked by a Forward of cost 3 or more.\" "
				+ "until the end of the turn.", null);
		assertNotNull(fn, "the suffix word order should parse");
		ForwardTarget chosen = new ForwardTarget(true, 2, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(chosen)));
		fn.accept(ctx);

		// Written into the per-Forward this-turn store, the same one a printed "cannot be blocked
		// by a Forward of cost N or more" is read from.
		verify(ctx).setP1ForwardCannotBeBlockedByCost(2, 3, true);
	}

	@Test
	void theSingleQuotedNestingIsTheSameGrant() {
		// 25-041C Thief prints this sentence inside a quoted option, so its double quotes are
		// already spent and the grant is nested in apostrophes.
		Consumer<GameContext> fn = ActionResolver.parse(
				"Choose 1 Forward. It gains 'This Forward cannot be blocked by a Forward of cost 4 or more.' "
				+ "until the end of the turn.", null);
		assertNotNull(fn);
		ForwardTarget chosen = new ForwardTarget(false, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(chosen)));
		fn.accept(ctx);

		verify(ctx).setP2ForwardCannotBeBlockedByCost(0, 4, true);
	}

	@Test
	void aPermanentQuotedGrantIsNotThisEffect() {
		// The shared pattern makes both "until the end of the turn" positions optional so one
		// regex covers the two printed word orders. A match with neither is a permanent grant,
		// and must not be resolved as a turn-scoped one.
		Matcher m = ActionResolverPatterns.FOLLOWUP_GAINS_QUOTED_ABILITY_UNTIL_EOT.matcher(
				"It gains \"This Forward cannot be blocked by a Forward of cost 3 or more.\"");
		assertTrue(m.find(), "the pattern still matches the sentence");
		assertNull(ActionResolver.quotedGrantUntilEot(m),
				"but the reader declines it, so the grant falls through as unhandled");
	}

	@Test
	void aGrantNamingSomeOtherCardIsNotThisForwards() {
		// 11-051C Tsukinowa's self-named printing of the same sentence belongs to the self-grant
		// path, which resolves it against the card that prints it.
		assertNull(ActionResolver.grantedThisForwardCannotBeBlockedByCost(
				"Tsukinowa cannot be blocked by a Forward of cost 5 or more."),
				"a quotation naming a card is about that card, not about whatever was chosen");
		assertNotNull(ActionResolver.grantedThisForwardCannotBeBlockedByCost(
				"This Forward cannot be blocked by a Forward of cost 5 or more."));
	}

	@Test
	void ninjaWithFiveBackupsCoversTheWholeRowInstead() {
		Consumer<GameContext> fn = ActionResolver.parse(NINJA_TEXT, null);
		assertNotNull(fn, "Ninja's trigger should parse");
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.controlConditionMet(any())).thenReturn(true);
		fn.accept(ctx);

		verify(ctx).grantOwnForwardsCannotBeBlockedByCost(3, true);
		// "instead" — the single-target branch must not also run.
		verify(ctx, never()).setP1ForwardCannotBeBlockedByCost(anyInt(), anyInt(), anyBoolean());
		verify(ctx, never()).setP2ForwardCannotBeBlockedByCost(anyInt(), anyInt(), anyBoolean());
	}

	@Test
	void ninjaWithoutFiveBackupsGrantsToOneForwardOnly() {
		Consumer<GameContext> fn = ActionResolver.parse(NINJA_TEXT, null);
		assertNotNull(fn);
		ForwardTarget chosen = new ForwardTarget(true, 0, ForwardTarget.CardZone.FORWARD);
		GameContext ctx = mock(GameContext.class);
		when(ctx.consumePreloadedTargets()).thenReturn(null);
		when(ctx.controlConditionMet(any())).thenReturn(false);
		when(ctx.selectCharacters(anyInt(), anyBoolean(), anyBoolean(), anyBoolean(), any(), any(),
				anyInt(), any(), anyInt(), any(), anyBoolean(), anyBoolean(), anyBoolean(),
				any(), any(), any(), any(), anyBoolean(), any(), anyBoolean()))
				.thenReturn(new ArrayList<>(List.of(chosen)));
		fn.accept(ctx);

		verify(ctx).setP1ForwardCannotBeBlockedByCost(0, 3, true);
		verify(ctx, never()).grantOwnForwardsCannotBeBlockedByCost(anyInt(), anyBoolean());
	}

	// ---- 23-049C Ninja on a real board ---------------------------------------------------------

	@Test
	void theGrantedRestrictionIsHonouredByTheBlockRules() {
		MainWindow mw = new MainWindow();
		CardData runner = makeForward("Runner", "Wind", 2, 5000);
		CardData other  = makeForward("Other", "Wind", 2, 5000);
		placeP1Forward(mw, runner);
		placeP1Forward(mw, other);

		assertFalse(mw.p1AttackerCostFiltersExclude(runner, 5),
				"nothing stops a cost 5 blocker before the grant");

		ActionResolver.parse(NINJA_MASS_CLAUSE, null).accept(mw.buildGameContext(true));

		assertTrue(mw.p1AttackerCostFiltersExclude(runner, 5),
				"a granted restriction is read by the same rule that reads a printed one");
		assertTrue(mw.p1AttackerCostFiltersExclude(other, 5), "and it covers every Forward in the row");
		assertFalse(mw.p1AttackerCostFiltersExclude(runner, 2),
				"a blocker under the threshold is still allowed");
	}

	// =========================================================================================
	// 29-087L Sephiroth — a self-cost reduction conditioned on the removed-from-game zone
	//
	// "If any Card Name Sephiroth you own are removed from the game, the cost required to cast
	// Sephiroth is reduced by 3." The zone it reads is the one the card's own ETF ability feeds
	// ("choose 1 Character you control. Remove it from the game"), so a board that has already
	// played one copy casts the next for 2 instead of 5.
	//
	// Two things separate it from the self-cost conditions already wired. It asks about ownership
	// rather than control — a removed card is in nobody's field — and "if any" is a yes/no: a
	// second removed copy pays no further discount. Both are what the tests below pin down.
	// =========================================================================================

	private static final String SEPHIROTH_29_087L_COST =
			"If any Card Name Sephiroth you own are removed from the game, "
			+ "the cost required to cast Sephiroth is reduced by 3.";

	/** Sephiroth as printed: cost 5, with her self-cost modifier parsed from her text. */
	private static CardData makeSephiroth() {
		return new CardData(null, "Sephiroth", "Lightning", 5, 9000, "Forward", false, 0, false, false,
				Set.of(), 0, List.of(), null, List.of(),
				List.of(), List.of(), CardData.parseFieldAbilities(SEPHIROTH_29_087L_COST, "Forward"),
				List.of(), List.of(), List.of(), List.of(),
				CardData.parseSelfCostModifiers(SEPHIROTH_29_087L_COST),
				List.of(), List.of(),
				false, false, null, false, false, false, false, false, 1,
				null, null, null, SEPHIROTH_29_087L_COST);
	}

	@Test
	void sephirothRfgConditionParsesAsAFlatNameLookup() {
		List<SelfCostModifier> mods = CardData.parseSelfCostModifiers(SEPHIROTH_29_087L_COST);

		assertEquals(1, mods.size(), "the sentence is one self-cost modifier");
		SelfCostModifier mod = mods.get(0);
		assertEquals(SelfCostModifier.ScalingType.IF_NAME_IN_RFP, mod.scalingType());
		assertEquals("Sephiroth", mod.param1());
		assertEquals(3, mod.amountPerUnit());
		assertFalse(mod.isIncrease());
		assertEquals(0, mod.minCost(), "no \"it cannot become 0\" rider is printed");
	}

	@Test
	void sephirothCostsHerPrintedCostWithNothingRemoved() {
		MainWindow mw = new MainWindow();
		assertEquals(5, mw.effectiveCastCost(makeSephiroth()));
	}

	@Test
	void sephirothCostsThreeLessWithACopyRemovedFromTheGame() {
		MainWindow mw = new MainWindow();
		CardData removed = makeForward("Sephiroth", "Lightning", 5, 9000);
		mw.gameState.getIdentity().put(removed, true);   // owned by P1
		mw.gameState.addToPermanentRfp(removed);

		assertEquals(2, mw.effectiveCastCost(makeSephiroth()));
	}

	@Test
	void aSecondRemovedCopyDiscountsNoFurther() {
		// "If any" is a yes/no, not a count — the distinction from an EACH_NAME_IN_BZ style scale.
		MainWindow mw = new MainWindow();
		for (int i = 0; i < 3; i++) {
			CardData removed = makeForward("Sephiroth", "Lightning", 5, 9000);
			mw.gameState.getIdentity().put(removed, true);
			mw.gameState.addToPermanentRfp(removed);
		}

		assertEquals(2, mw.effectiveCastCost(makeSephiroth()), "still one discount, not three");
	}

	@Test
	void someOtherCardRemovedFromTheGameIsNotSephiroth() {
		MainWindow mw = new MainWindow();
		CardData removed = makeForward("Cloud", "Lightning", 5, 9000);
		mw.gameState.getIdentity().put(removed, true);
		mw.gameState.addToPermanentRfp(removed);

		assertEquals(5, mw.effectiveCastCost(makeSephiroth()));
	}

	@Test
	void aSephirothTheOpponentOwnsDoesNotDiscountYours() {
		// The text says "you own". The removed-from-game zone is split by owner, so reading the
		// wrong half here would hand the discount to whichever player did not pay for it.
		MainWindow mw = new MainWindow();
		CardData removed = makeForward("Sephiroth", "Lightning", 5, 9000);
		mw.gameState.getIdentity().put(removed, false);  // owned by P2
		mw.gameState.addToPermanentRfp(removed);

		assertEquals(5, mw.effectiveCastCost(makeSephiroth()));
	}

	@Test
	void aSephirothInTheBreakZoneIsNotRemovedFromTheGame() {
		// The neighbouring condition (Astrius 24-091L) reads Break Zone *and* RFG together; this
		// one reads RFG alone, and the Break Zone must not stand in for it.
		MainWindow mw = new MainWindow();
		mw.gameState.getP1BreakZone().add(makeForward("Sephiroth", "Lightning", 5, 9000));

		assertEquals(5, mw.effectiveCastCost(makeSephiroth()));
	}

	// =========================================================================================
	// 9-014L Nael and family — "add up to M among them, rest to the Break Zone"
	//
	// Seven printings share this sentence, and none of them worked. The reveal/add family had a
	// pattern for every "return the other cards to the bottom of your deck" ending and, for the
	// Break-Zone ending, only the two special cases: "add 1 [Element|Category] card" and "add up
	// to M cards other than Card Name X". The plain "add up to M [Category X] [Type]" fell past
	// all of them into parse()'s compound-sentence fallback, which split on the full stop and read
	// "Add up to 2 Forwards among them to your hand" as a request to return a card *named* "up to
	// 2 Forwards among them" — logged in playtesting as
	//   [Warning] returnNamedCardToYourHand: "up to 2 Forwards among them" not found
	// so the cards were revealed and then nothing happened to them.
	// =========================================================================================

	private static final String NAEL_9_014L_ETF =
			"reveal the top 3 cards of your deck. Add up to 2 Forwards among them to your hand "
			+ "and put the rest of the cards into the Break Zone.";
	private static final String ZENOS_14_015R_ETF =
			"reveal the top 5 cards of your deck. Add up to 2 Category XIV Forwards among them to "
			+ "your hand and put the rest of the cards into the Break Zone.";
	private static final String MEIA_19_121H_ETF =
			"reveal the top 5 cards of your deck. Add up to 2 Category MOBIUS cards among them to "
			+ "your hand and put the rest of the cards into the Break Zone.";

	@Test
	void naelRevealAddsUpToTwoForwardsAndBinsTheRest() {
		Consumer<GameContext> fn = ActionResolver.parse(NAEL_9_014L_ETF, null);
		assertNotNull(fn, "Nael's enter-the-field reveal should parse");
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).revealTopAddUpToMatchingRestBz(3, 2, null, "Forward");
		// The bug: the second sentence used to be claimed as a return-a-named-card.
		verify(ctx, never()).returnNamedCardToYourHand(anyString());
	}

	@Test
	void naelIsAttributedToItsOwnParserRatherThanTheNamedReturn() {
		assertEquals("RevealTopNAddUpToMatchingRestBz",
				ActionResolver.matchedPatternName(NAEL_9_014L_ETF, null),
				"it used to report ReturnNamedToHand, which is what the warning came from");
	}

	@Test
	void aCategoryAndATypeAreBothCarriedThrough() {
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(ZENOS_14_015R_ETF, null).accept(ctx);
		verify(ctx).revealTopAddUpToMatchingRestBz(5, 2, "XIV", "Forward");
	}

	@Test
	void aCategoryWithoutATypeLeavesTheTypeFilterOpen() {
		// "Category MOBIUS cards" restricts the category and nothing else — a Summon qualifies.
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(MEIA_19_121H_ETF, null).accept(ctx);
		verify(ctx).revealTopAddUpToMatchingRestBz(5, 2, "MOBIUS", null);
	}

	@Test
	void theRestToBottomSiblingIsNotClaimedByTheBreakZoneParser() {
		// The two endings are what tell these apart; claiming the wrong one would send the
		// leftovers to the wrong zone silently.
		String toBottom = "reveal the top 5 cards of your deck. Add 2 Forwards among them to your "
				+ "hand and return the other cards to the bottom of your deck in any order.";
		assertNotEquals("RevealTopNAddUpToMatchingRestBz",
				ActionResolver.matchedPatternName(toBottom, null));
	}

	@Test
	void theAiTakesOnlyTheTypeTheRevealNames() {
		// Same eligibility test as the rest-to-bottom arm, so a filter means one thing throughout.
		List<CardData> cards = List.of(
				makeForward("Dear Forward", "Fire", 6, 9000),
				makeSummon("Costly Summon", "Fire", 7, ""),
				makeForward("Cheap Forward", "Fire", 1, 5000));
		DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestBz(cards, 2, null, "Forward");

		assertEquals(List.of(0, 2), d.toHand(), "both Forwards, dearest first — never the Summon");
		assertEquals(List.of(1), d.toBreak(), "the Summon is what the Break Zone gets");
		assertTrue(d.toBottom().isEmpty(), "this reveal has no bottom-of-deck destination");
	}

	@Test
	void theAiTakesNothingWhenNothingRevealedQualifies() {
		List<CardData> cards = List.of(
				makeSummon("Summon A", "Fire", 4, ""),
				makeSummon("Summon B", "Fire", 2, ""));
		DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestBz(cards, 2, null, "Forward");

		assertTrue(d.toHand().isEmpty(), "a reveal that turns up no Forward adds no Forward");
		assertEquals(List.of(0, 1), d.toBreak(), "and everything revealed still leaves the deck");
	}

	// =========================================================================================
	// Two playtest reports, both about a card that had left the board in one sense but not another
	//
	//   * A Brave attacker held the Attack Phase open after spending its declaration. Brave does
	//     not dull, and hasAttackableForward asked only whether a Forward was ACTIVE, while
	//     isForwardSelectable — what decides if you can actually click one — also asked whether it
	//     had an attack left. The phase kept asking for an attacker that could not be chosen.
	//
	//   * A Backup removed from the game as a cost stayed drawn on the field and never reached the
	//     RFG zone, yet stopped answering for CP. GameState.addToPermanentRfp routed by the owner
	//     map and unboxed a null for a card that map had never heard of, so it threw between
	//     clearing the slot and filing the card — leaving it in neither place.
	// =========================================================================================

	@Test
	void aSpentBraveAttackerNoLongerHoldsTheAttackPhaseOpen() {
		MainWindow mw = new MainWindow();
		CardData brave = makeForwardWithTraits("Brave One", "Fire", 9000,
				Set.of(CardData.Trait.BRAVE, CardData.Trait.HASTE));
		mw.placeCardInForwardZone(brave);
		mw.gameState.getIdentity().put(brave, true);

		assertTrue(mw.hasAttackableForward(), "Haste makes it attackable the turn it lands");

		mw.executeP1Attack(List.of(0));

		assertEquals(CardState.ACTIVE, mw.p1ForwardStates.get(0), "Brave does not dull on attack");
		assertFalse(mw.hasAttackRemaining(brave), "and its one declaration is spent");
		assertFalse(mw.hasAttackableForward(),
				"so the phase has nothing left to offer and must close rather than ask for another");
	}

	@Test
	void anUnspentBraveAttackerStillHoldsThePhaseOpen() {
		// The other side of the same rule: the fix must not close the phase on a Forward that can
		// still declare.
		MainWindow mw = new MainWindow();
		CardData brave = makeForwardWithTraits("Brave One", "Fire", 9000,
				Set.of(CardData.Trait.BRAVE, CardData.Trait.HASTE));
		mw.placeCardInForwardZone(brave);
		mw.gameState.getIdentity().put(brave, true);

		mw.executeP1Attack(List.of(0));
		mw.buildGameContext(true).grantMaxAttacksUntilEndOfTurn(brave, 2);

		assertTrue(mw.hasAttackableForward(),
				"a second declaration is available, so the phase still has an attacker to offer");
	}

	@Test
	void aFieldCardWithNoRecordedOwnerStillLeavesTheFieldWhenRemoved() {
		// Never registered in the owner map — which used to make removing it throw, stranding it.
		MainWindow mw = new MainWindow();
		CardData orphan = makePlainBackup("Red Mage", "Fire", 2);
		mw.p1BackupCards[0] = orphan;

		mw.buildGameContext(true).removeTargetFromGame(
				new ForwardTarget(true, 0, ForwardTarget.CardZone.BACKUP));

		assertNull(mw.p1BackupCards[0], "the slot it occupied is cleared");
		assertEquals(List.of(orphan), mw.gameState.getP1PermanentRfp(),
				"and it is filed with the side that removed it rather than lost between the two");
	}

	@Test
	void aRecordedOwnerStillBeatsTheSideDoingTheRemoving() {
		// Control changes hands and ownership does not, so a borrowed Backup removed from P1's
		// field belongs in P2's zone. The fallback is only for a card with no owner on record.
		MainWindow mw = new MainWindow();
		CardData borrowed = makePlainBackup("Borrowed Mage", "Fire", 2);
		mw.gameState.getIdentity().put(borrowed, false);
		mw.p1BackupCards[0] = borrowed;

		mw.buildGameContext(true).removeTargetFromGame(
				new ForwardTarget(true, 0, ForwardTarget.CardZone.BACKUP));

		assertTrue(mw.gameState.getP1PermanentRfp().isEmpty(), "not the controller's zone");
		assertEquals(List.of(borrowed), mw.gameState.getP2PermanentRfp(), "its owner's");
	}

	@Test
	void anUnownedRemovedCardCanStillBeCalledBack() {
		// The lookup half of the same map. A card filed under the fallback has to be findable
		// again, or anything that returns cards from the RFG zone would quietly leave it there.
		MainWindow mw = new MainWindow();
		CardData orphan = makePlainBackup("Red Mage", "Fire", 2);
		mw.p1BackupCards[0] = orphan;
		mw.buildGameContext(true).removeTargetFromGame(
				new ForwardTarget(true, 0, ForwardTarget.CardZone.BACKUP));

		assertTrue(mw.gameState.removeFromPermanentRfp(orphan), "found where it was filed");
		assertTrue(mw.gameState.getP1PermanentRfp().isEmpty());
	}

	// =========================================================================================
	// Removing a Backup from the game as a cost — Nael 9-014L, reported from playtesting as
	// "targeted Red Mage but it's still visibly on the field, and it isn't showing in the RFP
	// zone ... it's not showing during CP payments and Nael's ability doesn't see an eligible
	// backup."
	//
	// All four halves of that are one bug. refreshP1BackupSlot decides a slot is empty by asking
	// whether its *url* is null, not its card; removeTargetFromGame cleared only the card, so the
	// row stopped answering for CP and for targeting while the slot happily redrew the departed
	// card from the image cache. And the RFG label is painted from the zone list by
	// refreshWarpZoneUI, which the Backup and Monster branches never called.
	// =========================================================================================

	@Test
	void aBackupRemovedFromTheGameLeavesNothingBehindInItsSlot() {
		MainWindow mw = new MainWindow();
		CardData redMage = makePlainBackup("Red Mage", "Fire", 2);
		mw.gameState.getIdentity().put(redMage, true);
		mw.p1BackupCards[0] = redMage;
		mw.p1BackupUrls[0]  = "http://example.invalid/red-mage.jpg";

		mw.buildGameContext(true).removeTargetFromGame(
				new ForwardTarget(true, 0, ForwardTarget.CardZone.BACKUP));

		assertNull(mw.p1BackupCards[0], "gone from the row every rule reads");
		assertNull(mw.p1BackupUrls[0],
				"and from the url the slot repaints itself from — a stale url redrew the card "
				+ "that had just been removed from the game");
		assertEquals(List.of(redMage), mw.gameState.getP1PermanentRfp(), "and it is out of the game");
	}

	@Test
	void theSlotDoesNotCarryAFrozenFlagOverToTheNextBackup() {
		// p1BackupFrozen is indexed by slot, not by card, so leaving it set tints whatever lands
		// in that slot next. The break path clears it; this one used not to.
		MainWindow mw = new MainWindow();
		CardData frozen = makePlainBackup("Frozen Mage", "Fire", 2);
		mw.gameState.getIdentity().put(frozen, true);
		mw.p1BackupCards[0]  = frozen;
		mw.p1BackupUrls[0]   = "http://example.invalid/frozen.jpg";
		mw.p1BackupFrozen[0] = true;

		mw.buildGameContext(true).removeTargetFromGame(
				new ForwardTarget(true, 0, ForwardTarget.CardZone.BACKUP));

		assertFalse(mw.p1BackupFrozen[0], "the slot is clean for whoever occupies it next");
	}

	// =========================================================================================
	// 27-110H Bartz and 9-003L Ace — "Then shuffle the other cards and return them to the bottom"
	//
	// The same take-up-to-M shape as Nael's family, with a tail that matters: the cards nobody
	// took are shuffled *among themselves* and go under the deck in an order neither player knows.
	// That is not the "return the other cards to the bottom of your deck in any order" ending,
	// where the player arranges them and therefore does know — same cards, same destination,
	// different information — so it gets its own pattern and its own executor rather than being
	// folded into the existing bottom-of-deck reveals.
	//
	// Both had been falling through to parse()'s compound-sentence fallback and reporting as
	// ReturnNamedToHand, the same way Nael did.
	// =========================================================================================

	private static final String BARTZ_27_110H_ETF =
			"reveal the top 7 cards of your deck. Add up to 2 Category V cards among them to your "
			+ "hand. Then shuffle the other cards and return them to the bottom of your deck.";
	private static final String ACE_9_003L_ETF =
			"reveal the top 7 cards of your deck. Add up to 2 Job Class Zero Cadet other than Card "
			+ "Name Ace among them to your hand. Then, shuffle the other cards revealed and return "
			+ "them to the bottom of your deck.";

	@Test
	void bartzTakesUpToTwoOfACategoryAndShufflesTheRestUnderTheDeck() {
		Consumer<GameContext> fn = ActionResolver.parse(BARTZ_27_110H_ETF, null);
		assertNotNull(fn, "Bartz's enter-the-field reveal should parse");
		GameContext ctx = mock(GameContext.class);
		fn.accept(ctx);

		verify(ctx).revealTopAddUpToMatchingRestShuffledBottom(7, 2, null, "V", null, null);
		verify(ctx, never()).returnNamedCardToYourHand(anyString());
	}

	@Test
	void aceCarriesItsJobFilterAndItsSelfExclusion() {
		// "Job Class Zero Cadet other than Card Name Ace" — the Job group is lazy so that the
		// exclusion splits off at the right word rather than being swallowed into the Job name.
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(ACE_9_003L_ETF, null).accept(ctx);

		verify(ctx).revealTopAddUpToMatchingRestShuffledBottom(
				7, 2, "Class Zero Cadet", null, null, "Ace");
	}

	@Test
	void bothAreAttributedToTheShuffledBottomParser() {
		assertEquals("RevealTopNAddUpToMatchingRestShuffledBottom",
				ActionResolver.matchedPatternName(BARTZ_27_110H_ETF, null));
		assertEquals("RevealTopNAddUpToMatchingRestShuffledBottom",
				ActionResolver.matchedPatternName(ACE_9_003L_ETF, null));
	}

	@Test
	void theShuffledTailIsNotConfusedWithTheOrderedOne() {
		// The player orders the leftovers in this one, so it must keep its own parser.
		String ordered = "reveal the top 5 cards of your deck. Add up to 2 Forwards among them to "
				+ "your hand and return the other cards to the bottom of your deck in any order.";
		assertNotEquals("RevealTopNAddUpToMatchingRestShuffledBottom",
				ActionResolver.matchedPatternName(ordered, null));
	}

	@Test
	void theLeftoversGoUnderTheDeckRatherThanIntoTheBreakZone() {
		List<CardData> revealed = List.of(
				makeForward("Cadet A", "Fire", 5, 8000),
				makeForward("Cadet B", "Fire", 2, 5000),
				makeForward("Cadet C", "Fire", 3, 6000));
		DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestShuffledBottom(
				revealed, 1, null, null, null, null);

		assertEquals(List.of(0), d.toHand(), "the dearest card it is allowed");
		assertTrue(d.toBreak().isEmpty(), "nothing is binned by this effect");
		assertTrue(d.toTop().isEmpty(), "and nothing goes back on top");
		assertEquals(Set.of(1, 2), Set.copyOf(d.toBottom()), "the rest go under the deck");
	}

	@Test
	void aCategoryFilterDoesNotSilentlyExcludeSummons() {
		// Bartz says "Category V cards", not "Category V Characters". The shared reveal helper
		// narrows a bare Category to Characters — correct for the patterns that drop the printed
		// noun, wrong here, and it would have made a Category V Summon unselectable.
		CardData summon = makeSummon("Category V Summon", "Wind", 3, "");
		DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestShuffledBottom(
				List.of(summon), 1, null, null, null, null);

		assertEquals(List.of(0), d.toHand(), "a Summon is a card and may be taken");
	}

	@Test
	void anExcludedNameIsNeverTakenAndStillGoesUnderTheDeck() {
		List<CardData> revealed = List.of(
				makeForward("Ace", "Fire", 9, 9000),      // dearest, but excluded by name
				makeForward("Cadet", "Fire", 2, 5000));
		DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestShuffledBottom(
				revealed, 2, null, null, null, "Ace");

		assertEquals(List.of(1), d.toHand(), "only the card that is not an Ace");
		assertEquals(List.of(0), d.toBottom(), "and the Ace still leaves the reveal");
	}

	@Test
	void theLeftoversAreActuallyShuffledRatherThanKeptInRevealOrder() {
		// The contract is that nobody knows the resulting order, so the only honest assertion is
		// that the order varies. Five leftovers give 120 arrangements; 200 draws landing on one
		// arrangement every time would be beyond coincidence, so a single order here means the
		// shuffle is not happening at all.
		List<CardData> revealed = List.of(
				makeForward("A", "Fire", 1, 1000), makeForward("B", "Fire", 1, 1000),
				makeForward("C", "Fire", 1, 1000), makeForward("D", "Fire", 1, 1000),
				makeForward("E", "Fire", 1, 1000));
		Set<List<Integer>> seen = new java.util.HashSet<>();
		for (int i = 0; i < 200; i++) {
			DeckLookDecision d = LookAtDeckDialogs.cpuRevealAddUpToMatchingRestShuffledBottom(
					revealed, 0, null, null, null, null);
			assertEquals(Set.of(0, 1, 2, 3, 4), Set.copyOf(d.toBottom()),
					"every revealed card goes under the deck exactly once, however it is ordered");
			seen.add(d.toBottom());
		}
		assertTrue(seen.size() > 1, "the leftovers are shuffled, not returned in reveal order");
	}

	// =========================================================================================
	// The four remaining "Then, shuffle the other cards" cards
	//
	// Each pairs that tail with a different second mechanic, which is why they needed four pieces
	// of work rather than one: an optional price paid in your own board (Ardyn), a removal that
	// places a Warp Counter (Setzer), a permanent Element/Job grant on the card just played
	// (Chaos Advent), and a repeat of the whole action past a damage threshold (Vaan).
	//
	// All four had been unparsed or claimed by a fallback. Wiring Vaan also made the reveal-and-play
	// family's conflated tail matter for the first time: it read "shuffle the other cards" and
	// "return the other cards ... in any order" through one branch, which would have let the player
	// arrange leftovers the card says to shuffle.
	// =========================================================================================

	private static final String ARDYN_20_001R_ETF =
			"put 2 Backups you control into the Break Zone. If you do so, turn over one card at a "
			+ "time from the top of your deck until 2 Characters other than Card Name Ardyn are "
			+ "revealed. Play them onto the field. Then, shuffle the other cards revealed and "
			+ "return them to the bottom of your deck.";
	private static final String SETZER_29_103H_ETF =
			"reveal the top 7 cards of your deck. Remove 1 card with Warp among them from the game "
			+ "and place 1 Warp Counter on it. Then shuffle the other cards and return them to the "
			+ "bottom of your deck.";
	private static final String CHAOS_ADVENT_27_006R =
			"reveal the top 7 cards of your deck. Play up to 1 Category SOPFFO Forward among them "
			+ "onto the field. Then, shuffle the other cards revealed and return them to the bottom "
			+ "of your deck. The Forward's Element becomes Dark and it gains Job Chaos. (This "
			+ "effect does not end at the end of the turn.)";
	private static final String VAAN_10_133S_ETF =
			"reveal the top 5 cards of your deck. Play 1 Forward of cost 3 or less among them onto "
			+ "the field. Then, shuffle the other cards revealed and return them to the bottom of "
			+ "your deck. If you have received 5 points of damage or more, perform this action "
			+ "twice instead.";

	@Test
	void ardynBuysItsRevealWithTwoBackups() {
		GameContext ctx = mock(GameContext.class);
		Consumer<GameContext> fn = ActionResolver.parse(ARDYN_20_001R_ETF, null);
		assertNotNull(fn, "Ardyn's enter-the-field ability should parse");
		fn.accept(ctx);

		verify(ctx).putOwnTypeToBzThenDoSo(eq(2), eq("Backup"), any());
		assertEquals("PutOwnTypeToBzIfDoSo",
				ActionResolver.matchedPatternName(ARDYN_20_001R_ETF, null));
	}

	@Test
	void ardynsPriceIsPaidWithoutAskingTwice() {
		// The printed "you may" is the auto-ability's youMay flag, and the trigger has already put
		// that question to the player. With exactly the required number of Backups there is nothing
		// left to choose, so this resolves with no dialog at all — which is what makes it testable.
		MainWindow mw = new MainWindow();
		CardData a = makePlainBackup("Backup A", "Dark", 2);
		CardData b = makePlainBackup("Backup B", "Dark", 3);
		mw.gameState.getIdentity().put(a, true);
		mw.gameState.getIdentity().put(b, true);
		mw.p1BackupCards[0] = a;
		mw.p1BackupCards[1] = b;

		boolean[] ran = { false };
		mw.buildGameContext(true).putOwnTypeToBzThenDoSo(2, "Backup", c -> ran[0] = true);

		assertNull(mw.p1BackupCards[0], "both Backups are spent");
		assertNull(mw.p1BackupCards[1]);
		assertTrue(ran[0], "and what they bought resolves");
	}

	@Test
	void ardynBuysNothingWhenThePriceCannotBeMet() {
		MainWindow mw = new MainWindow();
		CardData only = makePlainBackup("Lonely Backup", "Dark", 2);
		mw.gameState.getIdentity().put(only, true);
		mw.p1BackupCards[0] = only;

		boolean[] ran = { false };
		mw.buildGameContext(true).putOwnTypeToBzThenDoSo(2, "Backup", c -> ran[0] = true);

		assertEquals(only, mw.p1BackupCards[0], "a partial payment buys nothing, so nothing is spent");
		assertFalse(ran[0], "and the effect does not resolve");
	}

	@Test
	void setzerRemovesAWarpCardAndPlacesACounterOnIt() {
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(SETZER_29_103H_ETF, null).accept(ctx);

		verify(ctx).revealTopNRemoveWarpCardPlaceCountersRestShuffledBottom(7, 1);
		assertEquals("RevealTopNRemoveWarpCardPlaceCountersRestShuffledBottom",
				ActionResolver.matchedPatternName(SETZER_29_103H_ETF, null));
	}

	/** A Forward that prints Warp N — what "a card with Warp" means to this reveal. */
	private static CardData makeWarpForward(String name, String element, int cost, int warpValue) {
		return new CardData(null, name, element, cost, 8000, "Forward", false, 0, false, false,
				Set.of(), warpValue, List.of(), null, List.of(),
				List.of(), List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
				List.of(), List.of(), List.of(),
				false, false, null, false, false, false, false, false, 1,
				null, null, null, "");
	}

	@Test
	void setzersPickLandsInTheWarpZoneWithOneCounter() {
		// A Warp Counter is what the Warp zone *is* — it ticks down and the card becomes castable
		// when it runs out — so the removed card belongs there rather than in the plain
		// removed-from-game pile. Resolved from P2's seat so the AI answers and no dialog opens.
		MainWindow mw = new MainWindow();
		CardData warped = makeWarpForward("Warper", "Wind", 5, 3);
		CardData plain  = makeForward("Plain", "Wind", 2, 5000);
		mw.gameState.getIdentity().put(warped, false);
		mw.gameState.getIdentity().put(plain, false);
		mw.gameState.getP2MainDeck().addLast(warped);
		mw.gameState.getP2MainDeck().addLast(plain);

		mw.buildGameContext(false).revealTopNRemoveWarpCardPlaceCountersRestShuffledBottom(2, 1);

		assertEquals(1, mw.gameState.getP2WarpZone().size(), "the card with Warp is taken");
		assertEquals(warped, mw.gameState.getP2WarpZone().get(0).card);
		assertEquals(1, mw.gameState.getP2WarpZone().get(0).counters,
				"one counter, as the ability says — not the card's printed Warp 3");
		assertTrue(mw.gameState.getP1WarpZone().isEmpty(), "and none of it touches the other seat");
	}

	@Test
	void setzerTakesNothingWhenNothingRevealedHasWarp() {
		MainWindow mw = new MainWindow();
		CardData plain = makeForward("Plain", "Wind", 2, 5000);
		mw.gameState.getIdentity().put(plain, false);
		mw.gameState.getP2MainDeck().addLast(plain);

		mw.buildGameContext(false).revealTopNRemoveWarpCardPlaceCountersRestShuffledBottom(1, 1);

		assertTrue(mw.gameState.getP2WarpZone().isEmpty(),
				"a card without Warp is not \"a card with Warp\"");
	}

	@Test
	void chaosAdventCarriesItsCategoryAndItsPermanentGrant() {
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(CHAOS_ADVENT_27_006R, null).accept(ctx);

		verify(ctx).revealTopNPlayCategoryTypeRestShuffledBottomGrantElementJob(
				7, 1, "SOPFFO", "Forward", "Dark", "Chaos");
		assertEquals("RevealPlayCategoryTypeRestShuffledBottomGrantElementJob",
				ActionResolver.matchedPatternName(CHAOS_ADVENT_27_006R, null));
	}

	@Test
	void vaanPerformsItsActionOnceBelowTheDamageThreshold() {
		GameContext ctx = mock(GameContext.class);
		when(ctx.ownDamageCount()).thenReturn(4);
		ActionResolver.parse(VAAN_10_133S_ETF, null).accept(ctx);

		verify(ctx, times(1)).revealTopNPlayUpToElementTypeCostOntoField(
				5, 1, null, "Forward", 3, RevealRest.SHUFFLED_BOTTOM);
	}

	@Test
	void vaanPerformsItTwiceAtFiveDamage() {
		GameContext ctx = mock(GameContext.class);
		when(ctx.ownDamageCount()).thenReturn(5);
		ActionResolver.parse(VAAN_10_133S_ETF, null).accept(ctx);

		verify(ctx, times(2)).revealTopNPlayUpToElementTypeCostOntoField(
				5, 1, null, "Forward", 3, RevealRest.SHUFFLED_BOTTOM);
	}

	@Test
	void vaansLeftoversAreShuffledRatherThanArrangedByThePlayer() {
		// The reveal-and-play family read "shuffle the other cards" and "return the other cards to
		// the bottom in any order" through one branch, so both arrived as RevealRest.BOTTOM — the
		// destination whose dialog lets the player set the order. Vaan is the first card to make
		// that difference reachable.
		GameContext ctx = mock(GameContext.class);
		when(ctx.ownDamageCount()).thenReturn(0);
		ActionResolver.parse(VAAN_10_133S_ETF, null).accept(ctx);

		verify(ctx, never()).revealTopNPlayUpToElementTypeCostOntoField(
				anyInt(), anyInt(), any(), any(), anyInt(), eq(RevealRest.BOTTOM));
	}

	@Test
	void theOrderedTailStillReachesTheOrderedDestination() {
		// The other half of that split: a card that really does let the player arrange the
		// leftovers must keep doing so.
		String ordered = "reveal the top 5 cards of your deck. Play 1 Forward of cost 3 or less "
				+ "among them onto the field and return the other cards to the bottom of your deck "
				+ "in any order.";
		GameContext ctx = mock(GameContext.class);
		ActionResolver.parse(ordered, null).accept(ctx);

		verify(ctx).revealTopNPlayUpToElementTypeCostOntoField(
				5, 1, null, "Forward", 3, RevealRest.BOTTOM);
	}

